insert into public.opportunities (source_id,external_id,canonical_url,application_url,guidelines_url,title,provider_name,opportunity_type,summary,description,disciplines,eligible_applicant_types,eligible_countries,eligible_regions,career_stages,award_min,award_max,currency,application_fee,deadline_at,deadline_timezone,opens_at,recurring,remote_allowed,travel_supported,accommodation_supported,fiscal_sponsor_allowed,language_requirements,education_requirements,organization_status_requirements,previous_award_restrictions,required_materials,participation_format,locations,application_mode,status,verification_status,source_published_at,source_updated_at,last_verified_at)
select s.id,r.external_id,r.canonical_url,r.application_url,r.guidelines_url,r.title,r.provider_name,r.opportunity_type,r.summary,r.description,r.disciplines,r.eligible_applicant_types,r.eligible_countries,r.eligible_regions,r.career_stages,r.award_min,r.award_max,r.currency,r.application_fee,r.deadline_at,r.deadline_timezone,r.opens_at,r.recurring,r.remote_allowed,r.travel_supported,r.accommodation_supported,r.fiscal_sponsor_allowed,r.language_requirements,r.education_requirements,r.organization_status_requirements,r.previous_award_restrictions,r.required_materials,r.participation_format,r.locations,r.application_mode,r.status,r.verification_status,r.source_published_at,now(),now()
from records r join public.opportunity_sources s on s.slug=r.source_slug
on conflict (source_id,external_id) do update set
  canonical_url=excluded.canonical_url, application_url=excluded.application_url,
  guidelines_url=excluded.guidelines_url, title=excluded.title, provider_name=excluded.provider_name,
  opportunity_type=excluded.opportunity_type, summary=excluded.summary, description=excluded.description,
  disciplines=excluded.disciplines, eligible_applicant_types=excluded.eligible_applicant_types,
  eligible_countries=excluded.eligible_countries, eligible_regions=excluded.eligible_regions,
  career_stages=excluded.career_stages, award_min=excluded.award_min, award_max=excluded.award_max,
  currency=excluded.currency, application_fee=excluded.application_fee,
  deadline_at=excluded.deadline_at, deadline_timezone=excluded.deadline_timezone,
  opens_at=excluded.opens_at, recurring=excluded.recurring, remote_allowed=excluded.remote_allowed,
  travel_supported=excluded.travel_supported, accommodation_supported=excluded.accommodation_supported,
  fiscal_sponsor_allowed=excluded.fiscal_sponsor_allowed,
  language_requirements=excluded.language_requirements, education_requirements=excluded.education_requirements,
  organization_status_requirements=excluded.organization_status_requirements,
  previous_award_restrictions=excluded.previous_award_restrictions,
  required_materials=excluded.required_materials, participation_format=excluded.participation_format,
  locations=excluded.locations, application_mode=excluded.application_mode, status=excluded.status,
  verification_status=excluded.verification_status, source_published_at=excluded.source_published_at,
  source_updated_at=excluded.source_updated_at, last_verified_at=excluded.last_verified_at, updated_at=now();

delete from public.opportunity_eligibility_rules r
using public.opportunities o, public.opportunity_sources s
where r.opportunity_id=o.id and o.source_id=s.id
  and s.slug in ('spain-culture-bdns','mexico-cultura','ibermusicas')
  and r.extraction_method='manual_review';

insert into public.opportunity_eligibility_rules (opportunity_id,rule_type,operator,value,requirement_level,source_text,source_url,source_field,extraction_method,verification_status,last_verified_at,sort_order)
