  ('spain-icaa-film-festivals-2026','applicant_type','in','["business","organization"]'::jsonb,'required','The official call supports eligible entities representing Spanish films at festivals.','official_call','ambiguous',1),
  ('mexico-fonart-gran-premio-2026','country_of_residence','in','["Mexico"]'::jsonb,'required','The official national call is for people practicing eligible Mexican craft traditions.','official_call','confirmed',1),
  ('mexico-fonart-gran-premio-2026','applicant_type','in','["individual_artist","artisan"]'::jsonb,'required','The official call is directed to individual artisans.','official_call','confirmed',2),
  ('mexico-fonart-grandes-maestros-2026','country_of_residence','in','["Mexico"]'::jsonb,'required','The official national call is for eligible Mexican artisans.','official_call','confirmed',1),
  ('mexico-fonart-grandes-maestros-2026','applicant_type','in','["individual_artist","artisan"]'::jsonb,'required','The official call is directed to individual artisans with specified prior awards.','official_call','confirmed',2),
  ('mexico-fonart-nacimientos-2026','country_of_residence','in','["Mexico"]'::jsonb,'required','The official national call is for artisans in Mexico.','official_call','confirmed',1),
  ('mexico-fonart-nacimientos-2026','applicant_type','in','["individual_artist","artisan"]'::jsonb,'required','The official call is directed to individual artisans who create Mexican nativity scenes.','official_call','confirmed',2),
  ('mexico-carlos-fuentes-2026','applicant_type','in','["organization","educational_institution","government"]'::jsonb,'required','Only eligible ministries, academies, educational institutions, and cultural institutions may submit nominations.','official_call','confirmed',1),
  ('ibermusicas-2026-circulacion','applicant_type','in','["individual_artist"]'::jsonb,'required','The official program describes this line for music professionals, artists, groups, researchers and other music-sector practitioners.','official_2026_guidelines','confirmed',1)
) x(external_id,rule_type,operator,value,requirement_level,source_text,source_field,verification_status,sort_order)
  on x.external_id=o.external_id
where s.slug in ('spain-culture-bdns','mexico-cultura','ibermusicas');

update public.opportunity_source_snapshots snap set is_current=false
from public.opportunities o join public.opportunity_sources s on s.id=o.source_id
where snap.opportunity_id=o.id and snap.is_current
  and s.slug in ('spain-culture-bdns','mexico-cultura','ibermusicas');

